/* v3.0 — viewer sees no edit/destructive controls */
.read-only #editPlayerBtn,
.read-only #viewDeletePlayerBtn,
.read-only #deletePlayerBtn,
.read-only #clearPlayersBtn,
.read-only #clearSquadsBtn{
  display:none !important;
}

/* v3.1 — remove black square around player cards on tactics pitch */
.slot-card.filled{
  background:transparent !important;
  background-image:none !important;
  border:none !important;
  box-shadow:none !important;
  border-radius:0 !important;
  overflow:visible !important;
  padding:0 !important;
}

.slot-card.filled img{
  background:transparent !important;
  border:none !important;
  box-shadow:none !important;
  border-radius:0 !important;
  display:block !important;
  object-fit:contain !important;
}

/* Remove any decorative pseudo-elements that can create a dark card/frame */
.slot-card.filled::before,
.slot-card.filled::after{
  display:none !important;
  content:none !important;
}

/* Uploaded transparent PNGs should remain transparent on the pitch */
.slot-card.filled img:not([src$="player-placeholder.png"]){
  mix-blend-mode:normal !important;
}

