/* =========================================================
   v5.23 — rebuilt LIGHT THEME
   Palette: warm ivory / paper white / graphite / restrained gold
   ========================================================= */
html[data-site-theme="light"]{
  --lt-bg:#f3f0e8;
  --lt-surface:#fffdf8;
  --lt-surface-2:#f8f4ea;
  --lt-surface-3:#eee8dc;
  --lt-text:#211f1a;
  --lt-muted:#777064;
  --lt-line:#ddd5c6;
  --lt-gold:#aa8128;
  --lt-gold-2:#d1ad52;
  --lt-green:#347a50;
  --lt-red:#a34a43;
}

/* Base */
html[data-site-theme="light"] body{
  background:var(--lt-bg)!important;
  color:var(--lt-text)!important;
}
html[data-site-theme="light"] .inner-screen{
  background:var(--lt-bg)!important;
  color:var(--lt-text)!important;
}
html[data-site-theme="light"] .screen-header,
html[data-site-theme="light"] .topbar{
  background:rgba(255,253,248,.96)!important;
  color:var(--lt-text)!important;
  border-bottom:1px solid var(--lt-line)!important;
  box-shadow:0 5px 18px rgba(56,45,24,.06)!important;
}
html[data-site-theme="light"] .screen-header h1,
html[data-site-theme="light"] .topbar h1{
  color:var(--lt-text)!important;
}
html[data-site-theme="light"] .eyebrow{
  color:var(--lt-gold)!important;
}

/* Cards and panels */
html[data-site-theme="light"] .settings-card,
html[data-site-theme="light"] .modal-card,
html[data-site-theme="light"] .tb-form-card,
html[data-site-theme="light"] .player-card,
html[data-site-theme="light"] .tactic-card,
html[data-site-theme="light"] .squad-card,
html[data-site-theme="light"] .gathering-card,
html[data-site-theme="light"] .chat-card,
html[data-site-theme="light"] .calendar-shell{
  background:var(--lt-surface)!important;
  color:var(--lt-text)!important;
  border-color:var(--lt-line)!important;
  box-shadow:0 7px 20px rgba(56,45,24,.055)!important;
}
html[data-site-theme="light"] .settings-card h2,
html[data-site-theme="light"] .modal-card h2,
html[data-site-theme="light"] .modal-card h3{
  color:var(--lt-text)!important;
}
html[data-site-theme="light"] .settings-hint,
html[data-site-theme="light"] .subline,
html[data-site-theme="light"] .muted{
  color:var(--lt-muted)!important;
}

/* Inputs */
html[data-site-theme="light"] input,
html[data-site-theme="light"] select,
html[data-site-theme="light"] textarea{
  background:#fff!important;
  color:var(--lt-text)!important;
  border:1px solid #d7cfbf!important;
  box-shadow:inset 0 1px 2px rgba(50,40,20,.035)!important;
}
html[data-site-theme="light"] input:focus,
html[data-site-theme="light"] select:focus,
html[data-site-theme="light"] textarea:focus{
  border-color:var(--lt-gold-2)!important;
