  box-shadow:0 0 0 3px rgba(190,151,55,.12)!important;
}
html[data-site-theme="light"] label{
  color:#5e584d!important;
}

/* Buttons */
html[data-site-theme="light"] .primary-btn,
html[data-site-theme="light"] .gold-btn{
  background:linear-gradient(180deg,#caa54e,#a77e27)!important;
  color:#fffdf7!important;
  border-color:#96701f!important;
