/* v5.26 — General statistics is a standalone swipe section */
.advanced-general-stats{
  width:min(94vw,760px);
  height:min(90vh,840px);
  padding:13px;
  overflow:hidden;
}
.general-stats-head{text-align:center;padding:0 30px 8px}
.general-stats-head h2{margin:3px 0 7px;font-size:17px}
.general-stats-dots{display:flex;justify-content:center;gap:5px;margin:5px 0 9px}
.general-stats-dots i{width:6px;height:6px;border-radius:50%;background:#444;transition:.2s}
.general-stats-dots i.active{width:18px;border-radius:10px;background:#d0ad51}
.general-stats-mode{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.general-mode-btn{
  border:1px solid #333;background:#111;color:#999;border-radius:9px;padding:8px 5px;
  font-size:8px;font-weight:900
}
.general-mode-btn.active{border-color:#c9a448;color:#e8c867;background:rgba(201,164,72,.1)}
.general-stats-viewport{height:calc(100% - 110px);overflow:hidden;touch-action:pan-y}
.general-stats-track{width:500%;height:100%;display:flex;transition:transform .28s ease}
.general-stats-slide{width:20%;height:100%;overflow-y:auto;box-sizing:border-box;padding:5px 3px 30px}
.general-stats-swipe-hint{text-align:center;color:#555;font-size:6px;letter-spacing:1px;margin-top:-15px}
.general-slide-summary,.general-section-label{text-align:center;color:#888;font-size:9px;font-weight:900;margin:5px 0 8px}
.general-stat-sort-4{grid-template-columns:repeat(4,1fr)!important}

.general-players-ranking{display:flex;flex-direction:column;gap:6px}
.general-player-full-row{
  width:100%;display:grid;grid-template-columns:28px 44px 1fr 48px;gap:7px;align-items:center;
  background:#0d0d0d;border:1px solid #292929;border-radius:11px;padding:8px;color:#fff;text-align:left
}
.general-player-full-row img{width:42px;height:42px;object-fit:contain}
.general-place{text-align:center;font-size:10px;color:#777;font-weight:1000}
.general-place.top-1{color:#e3bd4e}.general-place.top-2{color:#bfc2c5}.general-place.top-3{color:#b87d46}
.general-player-info{display:flex;flex-direction:column;gap:2px;min-width:0}
.general-player-info strong{font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.general-player-info small{font-size:7px;color:#777}
.general-player-full-row>b{text-align:right;color:#e4c25e;font-size:16px}

.general-streaks-list{display:flex;flex-direction:column;gap:7px}
.general-streak-card{position:relative;background:#0d0d0d;border:1px solid #2b2b2b;border-radius:11px;padding:9px}
.general-streak-card.best{border-color:#b99742}
.general-best-streak{position:absolute;right:8px;top:7px;color:#d2af51;font-size:6px;font-weight:1000}
.general-streak-player{display:flex;align-items:center;gap:7px;margin-bottom:6px}
.general-streak-player img{width:42px;height:42px;object-fit:contain}
.general-streak-player strong{font-size:10px}
.general-streak-line{display:grid;grid-template-columns:1fr 26px 60px;padding:5px 0;border-top:1px solid #222;align-items:center}
.general-streak-line span{font-size:8px;color:#aaa}.general-streak-line b{color:#e2c15e}.general-streak-line small{font-size:6px;color:#666;text-align:right}

.general-records-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.general-record-card{background:#0d0d0d;border:1px solid #2b2b2b;border-radius:11px;padding:9px}
.general-record-card>small{display:block;color:#b99a4d;font-size:6px;font-weight:900;margin-bottom:6px}
.general-record-winner{display:flex;gap:6px;align-items:center;margin-top:4px}
