  html[data-site-theme="light"] body:has(#screen-home.active),
  html.light-theme body:has(#screen-home.active){
    position:fixed!important;
    top:0!important;
    left:0!important;
    right:0!important;
    bottom:calc(-1 * env(safe-area-inset-bottom))!important;
    width:100%!important;
    height:calc(100dvh + env(safe-area-inset-bottom))!important;
    max-height:none!important;
    min-height:calc(100dvh + env(safe-area-inset-bottom))!important;
    overflow:visible!important;
    background:#745c26!important;
  }

  body:has(#screen-home.active) #app{
    position:absolute!important;
    inset:0!important;
    width:100%!important;
    height:calc(100dvh + env(safe-area-inset-bottom))!important;
    min-height:calc(100dvh + env(safe-area-inset-bottom))!important;
    max-height:none!important;
    overflow:visible!important;
