/* ==========================================================
   v8.31 TEST — UNIVERSAL BUTTON PRESS + IOS CHAT COMPOSER FIX
   ========================================================== */

/* Reliable tactile press feedback on every real button in both themes.
   Use the independent `scale` transform so controls that already have their
   own translate/rotate transform do not lose their geometry. */
button:not(:disabled){
  transition:
    transform .11s cubic-bezier(.2,.8,.2,1),
    scale .11s cubic-bezier(.2,.8,.2,1),
    filter .11s ease,
    box-shadow .14s ease,
    background-color .14s ease,
    border-color .14s ease!important;
  will-change:scale,filter;
}

button.ca-global-press-v831:not(:disabled){
  scale:.97!important;
  filter:brightness(.88) saturate(.96)!important;
}

button:not(:disabled):active{
  transform:scale(.97)!important;
  -webkit-transform:scale(.97)!important;
}

/* Do not scale actual draggable board objects; they get a brightness pulse
   only so their coordinate transforms remain untouched while dragging. */
#screen-tactical-board button.tb2-ball.ca-global-press-v831,
#screen-tactical-board button.tb-ball-object.ca-global-press-v831,
#screen-tactical-board button.tb-marker.ca-global-press-v831{
  scale:1!important;
