  max-height:100dvh!important;
  overflow:hidden!important;
  overscroll-behavior:none!important;
}
body:has(#screen-arena.active){
  position:fixed!important;
  top:0!important;
  right:0!important;
  bottom:0!important;
  left:0!important;
  width:100%!important;
  height:100dvh!important;
  min-height:100dvh!important;
  max-height:100dvh!important;
  margin:0!important;
  overflow:hidden!important;
  overscroll-behavior:none!important;
}
body:has(#screen-arena.active) #app{
  height:100dvh!important;
  min-height:100dvh!important;
  max-height:100dvh!important;
  overflow:hidden!important;
  overscroll-behavior:none!important;
}


/* ================================================================
   v11.57 — stable Arena keyboard viewport.
   iOS standalone can leave the DYNAMIC viewport shortened after the
   keyboard closes. All of the Arena canvas must instead use the large,
   keyboard-independent viewport; other routes retain their own styles.
   The shared dock retains the exact existing negative-safe-area gap.
   ================================================================ */
@supports (height:100lvh){
  html:has(#screen-arena.active),
  body:has(#screen-arena.active),
  body:has(#screen-arena.active) #app,
  body:has(#screen-arena.active) #screen-arena.active{
    height:100lvh!important;
    min-height:100lvh!important;
    max-height:100lvh!important;
  }
  /* The Arena content remains its own independently scrolling region. */
  body:has(#screen-arena.active) #screen-arena.active{
    position:fixed!important;
    inset:0!important;
    overflow-y:auto!important;
    overflow-x:hidden!important;
    -webkit-overflow-scrolling:touch!important;
    overscroll-behavior-y:contain!important;
  }
  /* Same initial Y as bottom:-safe-area, but calculated from the
     keyboard-INDEPENDENT full viewport height. The nav box height is
     measured from the existing Players dock, not a guessed pixel gap. */
  html body:has(#screen-arena.active) #app nav#bottomNav.bottom-nav:is(#bottomNav){
    position:fixed!important;
    top:calc(100lvh - var(--ca-arena-dock-box-h, 80px) + max(12px,env(safe-area-inset-bottom,0px)))!important;
    bottom:auto!important;
    inset:calc(100lvh - var(--ca-arena-dock-box-h, 80px) + max(12px,env(safe-area-inset-bottom,0px))) auto auto 50%!important;
    transform:translateX(-50%)!important;
    -webkit-transform:translateX(-50%)!important;
  }
}

/* v11.59 — clear, bottom-aligned confirmation after a player change request. */
.toast.player-request-success-v1159{
  z-index:12000!important;
  bottom:calc(105px + env(safe-area-inset-bottom,0px))!important;
  border-color:rgba(68,170,105,.72)!important;
  box-shadow:0 12px 36px rgba(0,0,0,.28)!important;
}
html[data-site-theme="light"] .toast.player-request-success-v1159,
html.light-theme .toast.player-request-success-v1159{
  border-color:rgba(44,138,76,.55)!important;
}
